<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>LAB-BRAND · 登录</title>
<style>
  :root{
    --brand:#1a73e8; --brand-dark:#1557b0; --danger:#d93025; --ok:#188038;
    --bg:#f5f7fa; --card:#fff; --border:#dadce0; --text:#202124; --muted:#5f6368;
  }
  *{box-sizing:border-box}
  body{margin:0;font-family:"PingFang SC","Microsoft YaHei","Helvetica Neue",Arial,sans-serif;
       background:var(--bg);color:var(--text);display:flex;align-items:center;justify-content:center;min-height:100vh}
  .card{width:400px;max-width:92vw;background:var(--card);border:1px solid var(--border);
        border-radius:12px;padding:40px 36px 32px;box-shadow:0 8px 24px rgba(32,33,36,.08)}
  .logo{display:flex;align-items:center;justify-content:center;gap:10px;margin-bottom:24px}
  .logo svg{width:36px;height:36px}
  .logo .word{font-size:24px;font-weight:600;letter-spacing:.5px}
  .logo .word b{color:var(--brand)}
