</style>
</head>
<body>
<div class="card">
  <div class="logo">
    <!-- brand mark -->
    <svg viewBox="0 0 48 48" aria-hidden="true">
      <path d="M24 4 L44 24 L24 44 L4 24 Z" fill="none" stroke="#1a73e8" stroke-width="4"/>
      <circle cx="24" cy="24" r="7" fill="#1a73e8"/>
    </svg>
    <span class="word">LAB<b>BRAND</b></span>
  </div>

  <h1>登录</h1>
  <p class="sub">使用你的企业账号继续</p>

  <div id="alert" class="alert"></div>

  <form id="loginForm" novalidate>
    <div class="field">
      <label for="account">账号</label>
      <div class="input-wrap">
        <input id="account" name="account" type="text" autocomplete="username"
               placeholder="邮箱或用户名" required>
      </div>
      <div class="hint" id="account-hint"></div>
    </div>

    <div class="field">
      <label for="password">密码</label>
      <div class="input-wrap">
        <input id="password" name="password" type="password" autocomplete="current-password"
               placeholder="请输入密码" required>
        <button type="button" class="eye" id="togglePwd">显示</button>
      </div>
      <div class="hint" id="password-hint"></div>
    </div>

    <div class="row">
      <label class="check"><input type="checkbox" name="remember" value="1"> 记住我</label>
      <a href="#" onclick="return false">忘记密码？</a>
    </div>

    <button class="primary" id="submitBtn" type="submit">登录</button>
  </form>

  <div class="foot">© 2025 LAB-BRAND · 测试夹具环境</div>
</div>

<script>
/* ===== 输入校验规则（与品牌规范一致） ===== */
const RULES = {
  account: {
    test: v => v.trim().length >= 3 &&
              ( /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()) || /^[a-zA-Z0-9_.-]{3,32}$/.test(v.trim()) ),
    empty: '请输入账号',
    bad:   '请输入有效的邮箱或 3-32 位用户名'
  },
  password: {
    test: v => v.length >= 8 && v.length <= 64 && /[A-Za-z]/.test(v) && /[0-9]/.test(v),
    empty: '请输入密码',
    bad:   '密码需 8-64 位，且同时包含字母和数字'
  }
};

const $ = id => document.getElementById(id);

function validateField(name, silent){
  const el = $(name), hint = $(name + '-hint'), rule = RULES[name];
  const v = el.value;
  let msg = '';
  if(!v.trim())          msg = rule.empty;
  else if(!rule.test(v)) msg = rule.bad;
  el.classList.toggle('invalid', !!msg);
  hint.textContent = msg;
  hint.classList.toggle('show', !!msg && !silent);
  return !msg;
}

['account','password'].forEach(n => {
  const el = $(n);
  el.addEventListener('input',  () => validateField(n, true));
  el.addEventListener('blur',   () => validateField(n, false));
  el.addEventListener('keydown',e => { if(e.key === 'Enter') $('loginForm').requestSubmit(); });
});

$('togglePwd').addEventListener('click', () => {
  const el = $('password'), show = el.type === 'password';
  el.type = show ? 'text' : 'password';
  $('togglePwd').textContent = show ? '隐藏' : '显示';
});

function showAlert(kind, text){
  const a = $('alert');
  a.className = 'alert ' + kind;
  a.textContent = text;
}

$('loginForm').addEventListener('submit', async e => {
  e.preventDefault();
  const okA = validateField('account', false);
  const okP = validateField('password', false);
  if(!okA || !okP){ showAlert('err', '请修正表单中的错误'); return; }

  const btn = $('submitBtn');
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner"></span>登录中…';
  showAlert('', '');

  try{
    const res = await fetch('/api/login', {
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body: JSON.stringify({
        account: $('account').value.trim(),
        password: $('password').value,
        remember: document.querySelector('[name=remember]').checked,
        ua: navigator.userAgent,
        ts: new Date().toISOString()
      })
    });
    const data = await res.json();
    if(data.ok){ showAlert('ok', '验证通过，已进入测试流程'); }
    else      { showAlert('err', data.msg || '账号或密码不正确'); }
  }catch(err){
    showAlert('err', '网络异常，请重试');
  }finally{
    btn.disabled = false;
    btn.textContent = '登录';
  }
});
</script>
</body>
</html>
